// Sample data (read-only) — ClinicCare.
const STAKEHOLDERS = [
 {
  "name": "Clinic owner",
  "power": 5,
  "interest": 4
 },
 {
  "name": "Health ministry",
  "power": 5,
  "interest": 2
 },
